// Turn ranked.csv (the stdout of the last step) into one item per shortlisted lead.
const text = $input.first().json.stdout;
const rows = [];
let row = [], field = '', quoted = false;
for (let i = 0; i < text.length; i++) {
  const c = text[i];
  if (quoted) {
    if (c === '"' && text[i + 1] === '"') { field += '"'; i++; }
    else if (c === '"') quoted = false;
    else field += c;
  } else if (c === '"') quoted = true;
  else if (c === ',') { row.push(field); field = ''; }
  else if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; }
  else if (c !== '\r') field += c;
}
if (field !== '' || row.length) { row.push(field); rows.push(row); }
const head = rows.shift();
const records = rows.filter(r => r.length === head.length).map(r => Object.fromEntries(head.map((h, i) => [h, r[i]])));
const top = records.filter(r => r.status !== 'knocked out').slice(0, 10);
return top.map(r => ({ json: { rank: Number(r.rank), score: Number(r.score), title: r.title, company: r.company, url: r.url, status: r.status, incomplete: r.incomplete, reasons: r.reasons } }));
